import { db } from '../db/connection';
import { sessions, users } from '../db/schema';
import { sendWelcomeEmail } from '../notifications/email';
import { trackEvent } from '../billing/usage';
import { hash, verify } from '../shared/crypto';
import { validateEmail } from '../shared/validation';

export class AuthHandler {
  async register(email: string, password: string) {
    validateEmail(email);
    const hashed = await hash(password);
    const user = await db.insert(users).values({ email, password: hashed }).returning();
    await sendWelcomeEmail(user[0].email);
    await trackEvent(user[0].id, 'registration');
    return this.createSession(user[0].id);
  }

  async login(email: string, password: string) {
    const user = await db.select().from(users).where({ email }).first();
    if (!user || !(await verify(password, user.password))) {
      throw new Error('Invalid credentials');
    }
    return this.createSession(user.id);
  }

  private async createSession(userId: string) {
    return db.insert(sessions).values({ userId, expiresAt: new Date(Date.now() + 86400000) }).returning();
  }
}

