import { db } from './db';
import { sessions, users } from './schema';
import { hash, verify } from './crypto';
import { validateEmail } from './validation';
import { publishEvent } from './events';

export class AuthHandler {
  async register(email: string, password: string) {
    validateEmail(email);
    const hashed = await hash(password);
    const user = await db.insert(users).values({ email, password: hashed }).returning();
    // Publish event instead of direct call
    await publishEvent('user.registered', { userId: user[0].id, email: user[0].email });
    return this.createSession(user[0].id);
  }

  async login(email: string, password: string) {
    const user = await db.select().from(users).where({ email }).first();
    if (!user || !(await verify(password, user.password))) {
      throw new Error('Invalid credentials');
    }
    return this.createSession(user.id);
  }

  private async createSession(userId: string) {
    return db.insert(sessions).values({ userId, expiresAt: new Date(Date.now() + 86400000) }).returning();
  }
}

import { connect } from 'amqplib';

const RABBITMQ_URL = process.env.RABBITMQ_URL || 'amqp://localhost';

export async function publishEvent(type: string, payload: Record<string, unknown>) {
  const conn = await connect(RABBITMQ_URL);
  const channel = await conn.createChannel();
  await channel.assertExchange('events', 'topic', { durable: true });
  channel.publish('events', type, Buffer.from(JSON.stringify({ type, payload, timestamp: new Date().toISOString() })));
  await channel.close();
  await conn.close();
}

import express from 'express';
import { AuthHandler } from './handler';

const app = express();
app.use(express.json());

const auth = new AuthHandler();

app.post('/auth/register', async (req, res) => {
  try {
    const session = await auth.register(req.body.email, req.body.password);
    res.json({ session });
  } catch (e) {
    res.status(400).json({ error: e.message });
  }
});

app.post('/auth/login', async (req, res) => {
  try {
    const session = await auth.login(req.body.email, req.body.password);
    res.json({ session });
  } catch (e) {
    res.status(401).json({ error: e.message });
  }
});

app.listen(3001, () => console.log('Auth service running on :3001'));

