import Stripe from 'stripe';
import { db } from '../db/connection';
import { users, subscriptions, invoices } from '../db/schema';
import { sendInvoiceEmail } from '../notifications/email';
import { getUser } from '../users/model';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export async function createSubscription(userId: string, planId: string) {
  const user = await getUser(userId);
  if (!user.stripeCustomerId) {
    const customer = await stripe.customers.create({ email: user.email });
    await db.update(users).set({ stripeCustomerId: customer.id }).where({ id: userId });
    user.stripeCustomerId = customer.id;
  }
  const subscription = await stripe.subscriptions.create({
    customer: user.stripeCustomerId,
    items: [{ price: planId }],
  });
  await db.insert(subscriptions).values({ userId, stripeSubscriptionId: subscription.id, planId, status: 'active' });
  await sendInvoiceEmail(user.email, subscription.latest_invoice as string);
  return subscription;
}

